async def s3_list_async(url: str) -> Tuple[bool, list]:
    """List directory contents from S3 asynchronously.

    Args:
        url: S3 URL in format s3://endpoint/bucket/prefix

    Returns:
        Tuple[bool, list]: (success, entries) where entries is a list of MockEntry objects
    """
    try:
        init_vendored_packages()
        from botocore.exceptions import ClientError

        endpoint, bucket, prefix = parse_s3_url(url)

        # Ensure prefix ends with '/' if it exists and doesn't already
        if prefix and not prefix.endswith('/'):
            prefix += '/'

        entries = []

        async with get_async_s3_client(endpoint) as client:
            paginator = client.get_paginator('list_objects_v2')

            # List objects with the given prefix
            async for page in paginator.paginate(Bucket=bucket, Prefix=prefix, Delimiter='/'):
                # Add directories (common prefixes)
                for prefix_info in page.get('CommonPrefixes', []):
                    class MockEntry:
                        def __init__(self, prefix_path):
                            # Remove the base prefix to get relative path
                            rel_path = prefix_path[len(prefix):] if prefix else prefix_path
                            self.relative_path = rel_path.rstrip('/')
                            self.size = 0
                            self.modified_time = 0
                            self.flags = omni.client.ItemFlags.CAN_HAVE_CHILDREN

                    entries.append(MockEntry(prefix_info['Prefix']))

                # Add files
                for obj in page.get('Contents', []):
                    # Skip the directory itself
                    if obj['Key'] == prefix:
                        continue

                    class MockEntry:
                        def __init__(self, obj_data):
                            # Remove the base prefix to get relative path
                            full_key = obj_data['Key']
                            rel_path = full_key[len(prefix):] if prefix else full_key
                            self.relative_path = rel_path
                            self.size = obj_data['Size']
                            self.modified_time = obj_data['LastModified'].timestamp()
                            self.flags = 0  # Regular file

                    entries.append(MockEntry(obj))

        return True, entries

    except ClientError as e:
        if e.response['Error']['Code'] == 'NoSuchBucket':
            carb.log_info(f"S3 bucket not found: {bucket}")
            return False, []
        carb.log_info(f"S3 error in list_async: {e}")
        return False, []
    except Exception as e:
        carb.log_info(f"S3 error in list_async: {e}")
        return False, []
